MediaScreen

// MediaScreen.js — экран мультимедиа
import React, { useState, useRef } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  Image, 
  StyleSheet, 
  ScrollView, 
  Alert 
} from 'react-native';

import * as ImagePicker from 'expo-image-picker';
import { Audio } from 'expo-av';
import * as Haptics from 'expo-haptics';

const MediaScreen = () => {
  const [imageUri, setImageUri] = useState(null);
  const [recording, setRecording] = useState(null);
  const [sound, setSound] = useState(null);
  const soundRef = useRef(null);

  const takePhoto = async () => {
    const { status } = await ImagePicker.requestCameraPermissionsAsync();
    if (status !== 'granted') {
      Alert.alert("Ошибка", "Разрешение на камеру не предоставлено");
      return;
    }
    const result = await ImagePicker.launchCameraAsync();
    if (!result.canceled) {
      setImageUri(result.assets[0].uri);
    }
  };

  const pickImage = async () => {
    const result = await ImagePicker.launchImageLibraryAsync();
    if (!result.canceled) {
      setImageUri(result.assets[0].uri);
    }
  };

  const playSignal = async () => {
    try {
      const { sound } = await Audio.Sound.createAsync(
        require('../../assets/signal.mp3')
      );
      soundRef.current = sound;
      await sound.playAsync();
    } catch (e) {
      Alert.alert("Ошибка", "Не удалось воспроизвести сигнал");
    }
  };

  const startRecording = async () => {
    const perm = await Audio.requestPermissionsAsync();
    if (perm.status !== 'granted') {
      Alert.alert("Ошибка", "Нет доступа к микрофону");
      return;
    }

    await Audio.setAudioModeAsync({
      allowsRecordingIOS: true,
      playsInSilentModeIOS: true,
    });

    const recording = new Audio.Recording();
    await recording.prepareToRecordAsync(
      Audio.RECORDING_OPTIONS_PRESET_HIGH_QUALITY
    );
    await recording.startAsync();

    setRecording(recording);
  };

  const stopRecording = async () => {
    await recording.stopAndUnloadAsync();
    const uri = recording.getURI();
    const { sound } = await recording.createNewLoadedSoundAsync();
    setSound(sound);
    setRecording(null);
  };

  return (
    <ScrollView style={styles.container}>

      {/* Работа с изображениями */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Работа с изображениями</Text>

        <View style={styles.row}>
          <TouchableOpacity style={styles.buttonGreen} onPress={takePhoto}>
            <Text style={styles.buttonText}>Сделать фото</Text>
          </TouchableOpacity>

          <TouchableOpacity style={styles.buttonBlue} onPress={pickImage}>
            <Text style={styles.buttonText}>Выбрать из галереи</Text>
          </TouchableOpacity>
        </View>

        {imageUri && (
          <Image 
            source={{ uri: imageUri }} 
            style={styles.preview}
          />
        )}
      </View>


      {/* Работа с аудио */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Работа с аудио</Text>

        <TouchableOpacity style={styles.buttonPurple} onPress={playSignal}>
          <Text style={styles.buttonText}>Воспроизвести сигнал</Text>
        </TouchableOpacity>

        <View style={styles.row}>
          <TouchableOpacity 
            style={styles.buttonRed} 
            onPress={startRecording}
            disabled={recording !== null}
          >
            <Text style={styles.buttonText}>Начать запись</Text>
          </TouchableOpacity>

          <TouchableOpacity 
            style={styles.buttonOrange}
            onPress={stopRecording}
            disabled={recording === null}
          >
            <Text style={styles.buttonText}>Слушать запись</Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* Блок "Описание" — УДАЛЁН */}

    </ScrollView>
  );
};
